d5(implode('|', $data)), 0, 16); } private function getClientIP(): string { $ip = $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0'; if (!filter_var ($ip, FILTER_VALIDATE_IP)) { $ip = '0.0.0.0'; } return $ip; } private function isWhitelisted(): bool { if (in_array($this->clientIP, self::WHITELIST_IPS)) { return true; } $uri = $_SERVER['REQUEST_URI'] ?? ''; foreach (self::WHITELIST_PATHS as $path) { if (str_starts_with($uri, $path)) { return true; } } $path = parse_url($uri, PHP_URL_PATH) ?? ''; $ext = strtolower(pathinfo($path, PATHINFO_EXTENSION)); if (in_array($ext, self::WHITELIST_EXTENSIONS)) { return true; } return false; } private function initStorage(): void { if (self::$initialized) { return; } $currentTime = time(); foreach (self::$blacklist as $ip => $banUntil) { if ($currentTime >= $banUntil) { unset(self::$blacklist[$ip]); } } foreach (self::$requestRecords as $ip => $records) { self::$requestRecords[$ip] = array_filter($records, function ($timestamp) use ($currentTime) { return ($currentTime - $timestamp) <= self::CC_TIME_WINDOW; }); if (empty(self::$requestRecords[$ip])) { unset(self::$requestRecords[$ip]); } } if (count(self::$scanCache) > 1000) { self::$scanCache = array_slice(self::$scanCache, -500, 500, true); } self::$initialized = true; } private function checkFileUpload(): bool { if (empty($_FILES)) { return false; } foreach ($_FILES as $file) { if ($file['error'] !== UPLOAD_ERR_OK) { continue; } $fileName = $file['name']; $fileExt = strtolower(pathinfo($fileName, PATHINFO_EXTENSION)); if (in_array($fileExt, self::FORBIDDEN_EXTENSIONS)) { return true; } $parts = explode('.', $fileName); if (count($parts) > 2) { $lastExt = strtolower(end($parts)); if (in_array($lastExt, self::FORBIDDEN_EXTENSIONS)) { return true; } } if (file_exists($file['tmp_name'])) { $finfo = finfo_open(FILEINFO_MIME_TYPE); $mimeType = finfo_file($finfo, $file['tmp_name']); finfo_close($finfo); $dangerousMime = [ 'application/x-php', 'text/x-php', 'application/php', 'application/x-httpd-p