vice-width,initial-scale=1.0"><title>请求被阻止</title><style>' . $css . '</style></head><body><div class="container"><div class="header"><h1>' . $blockIcon . ' 请求被阻止</h1><div class="sub">' . $subText . '<span class="badge ' . $badgeClass . '">已拦截</span></div></div><div class="info"><div class="info-item"><span class="label">请求ID</span><span class="value">' . $this->requestId . '</span></div><div class="info-item"><span class="label">检测类型</span><span class="value">' . $blockTypeLabel . '</span></div><div class="info-item"><span class="label">检测原因</span><span class="value">' . htmlspecialchars($this->blockReason) . '</span></div><div class="info-item"><span class="label">请求IP</span><span class="value">' . $this->clientIP . '</span></div><div class="info-item"><span class="label">请求URI</span><span class="value">' . $uri . '</span></div><div class="info-item"><span class="label">请求方法</span><span class="value">' . $method . '</span></div><div class="info-item"><span class="label">请求路径</span><span class="value">' . htmlspecialchars($this->blockPath) . '</span></div><div class="info-item"><span class="label">时间</span><span class="value">' . $time . '</span></div>' . $banInfoHtml . '</div>' . $noteHtml . '<a href="javascript:history.back()" class="btn-back">← 返回上一页</a><div class="footer">由嗷呜awaのWebSafe强力保护|检测器版本:Xsafe4.3|Xsafe.awaone.cn</div></div></body></html>'; } public static function sanitize(string $input): string { $input = strip_tags($input); $input = htmlspecialchars($input, ENT_QUOTES | ENT_HTML5, 'UTF-8'); $input = trim($input); return $input; } } new InjectionGuard(); if (!function_exists('safe_input')) { function safe_input(string $key, $default = null, string $method = 'REQUEST') { $value = null; switch (strtoupper($method)) { case 'GET': $value = $_GET[$key] ?? $default; break; case 'POST': $value = $_POST[$key] ?? $default; break; case 'REQUEST': $value = $_REQUEST[$key] ?? $default; break; case 'COOKIE': $value = $_COOKIE[$key] ?? $default; break; default: return $default; } if (is_array($value)) { return array_map(function ($item) { return InjectionGuard::sanitize((string)$item); }, $value); } return InjectionGuard::sanitize((string)$value); } } if (!function_exists('safe_output')) { function safe_output(string $text): string { return htmlspecialchars($text, ENT_QUOTES | ENT_HTML5, 'UTF-8'); } } if (!function_exists('safe_sql')) { function safe_sql(string $value): string { $dangerous = ['union', 'select', 'insert', 'update', 'delete', 'drop', 'truncate']; foreach ($dangerous as $keyword) { $value = preg_replace('/\b' . $keyword . '\b/i', '', $value); } return addslashes($value); } } ?>